<script setup lang="ts">import{ref,onMounted}from 'vue';import{useRouter}from 'vue-router';import{lab,load}from '../stores/research';import{canEdit}from '../stores/auth';import*as runs from '../api/runs';import{useTask}from '../hooks/useTask';import{usePolling}from '../hooks/usePolling';import StudySelect from '../components/StudySelect.vue';import PageHeading from '../components/common/PageHeading.vue';import ErrorNotice from '../components/common/ErrorNotice.vue';import StatusBadge from '../components/common/StatusBadge.vue';import type{RunType}from '../types/domain';const selected=ref(0),name=ref('预设湿度层 · 独立封装复核'),alpha=ref(.05),runType=ref<RunType>('layerwise_exact'),router=useRouter(),{error,busy,execute}=useTask();onMounted(()=>execute(async()=>{await load();selected.value=lab.studies[0]?.id||0}));usePolling(()=>{if(lab.runs.some(r=>['queued','running'].includes(r.status)))execute(load)});function submit(){execute(async()=>{const r=await runs.create({name:name.value,study_id:selected.value,alpha:alpha.value,run_type:runType.value});await load();router.push('/results?run='+r.id)})}</script><template><PageHeading index="03" title="冻结边际，再计算证据。" text="研究提交时冻结全部层、四格计数与批注；独立worker计算，不在浏览器拼造结果。"/><ErrorNotice :message="error" @retry="execute(load)"/><div class="configure-grid"><form v-if="canEdit" @submit.prevent="submit"><StudySelect :studies="lab.studies" v-model="selected"/><label>研究类型<select v-model="runType" aria-label="研究类型"><option value="layerwise_exact">全层检验：CMH与固定边际均值距离精确双侧（沿用原口径）</option><option value="interval_scan">区间扫描：冻结层顺序上全部连续区间的最大偏离，全局精确尾</option></select></label><label>研究名称<input v-model="name" minlength="3" maxlength="160" required/></label><label>预设探索阈值 alpha<input v-model.number="alpha" type="number" min=".001" max=".1" step=".001" required/></label><p class="margin-note">alpha只用于阅读预先声明的条件检验，不调整数据、分层或概率。无连续性修正、无零格加.5。区间扫描不做逐区间独立检验或多重性调整；预计内存超过1GiB时拒绝计算。</p><button class="primary" :disabled="busy||!selected">冻结并送入计算队列 →</button></form><aside><p class="eyebrow">TWO READINGS OF THE SAME MARGINS</p><h2>渐近，与精确。<br>各自写清口径。</h2><p>CMH = (Σa − ΣE[a])² / ΣVar[a]，渐近 χ²₁只作对照。</p><p>固定各层行列边际，卷积每层超几何分布；全层检验按S距零假设均值的绝对距离纳入双侧尾。</p><p>区间扫描冻结预先声明的层顺序与计数，对全部连续区间取 |Σ(a−E[a])| 的最大值，在同一固定边际联合分布上计算含并列的全局精确尾概率，无模拟替代。</p><p>共同OR是分层汇总，不检验同质性，不作工艺因果归因。</p></aside></div><section class="run-ledger"><h2>研究队列</h2><article v-for="r in lab.runs" :key="r.id"><div><span>#{{r.id}}</span><h3>{{r.name}}</h3><small>底稿{{r.study_id}} · α{{r.alpha}} · {{r.run_type==='interval_scan'?'区间扫描':'全层检验'}}</small></div><StatusBadge :status="r.status"/><RouterLink :to="'/results?run='+r.id">读取冻结研究 ↗</RouterLink></article></section></template>
